-- Shared with master-pss: private, client-scoped rate-card metadata and bucket.
insert into public.permissions (permission_key, label, description, permission_group) values ('rate_cards.manage', 'Manage rate cards', 'Upload and replace rate cards for assigned clients.', 'Clients') on conflict (permission_key) do update set label = excluded.label, description = excluded.description, permission_group = excluded.permission_group;
create table if not exists public.rate_cards (id uuid primary key default gen_random_uuid(), client_id uuid not null unique references public.client_accounts(id) on delete cascade, object_path text not null unique, original_filename text not null, mime_type text not null check (mime_type in ('application/pdf', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')), byte_size bigint not null check (byte_size > 0 and byte_size <= 10485760), uploaded_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.rate_cards enable row level security;
drop policy if exists rate_cards_read_scope on public.rate_cards;
create policy rate_cards_read_scope on public.rate_cards for select to authenticated using (public.is_super_admin() or (public.has_permission('rate_cards.manage') and public.is_employee_assigned(client_id)));
drop policy if exists rate_cards_write_scope on public.rate_cards;
create policy rate_cards_write_scope on public.rate_cards for all to authenticated using (public.is_super_admin() or (public.has_permission('rate_cards.manage') and public.is_employee_assigned(client_id))) with check (public.is_super_admin() or (public.has_permission('rate_cards.manage') and public.is_employee_assigned(client_id)));
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('rate-cards', 'rate-cards', false, 10485760, array['application/pdf', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict (id) do update set public = false, file_size_limit = 10485760, allowed_mime_types = excluded.allowed_mime_types;
